<template><PageShell title="外向交货" tcode="VL01N"><template #actions><el-button type="primary" @click="visible=true">从销售订单创建</el-button></template><el-card><el-table :data="rows" border stripe><el-table-column prop="vbeln" label="交货单" /><el-table-column prop="soVbeln" label="销售订单" /><el-table-column prop="kunnr" label="客户" /><el-table-column prop="status" label="状态"><template #default="{row}"><StatusTag :value="row.status" /></template></el-table-column><el-table-column label="BMS同步"><template #default="{row}"><StatusTag :value="row.bmsStatus || row.syncStatus" /><el-button link @click="repush(row)">重推</el-button></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link :disabled="row.status!=='OPEN'" @click="pick(row)">拣配</el-button><el-button link :disabled="row.status!=='PICKED'" @click="pgi(row)">发货过账</el-button><el-button link @click="show(row)">明细</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="visible" title="从销售订单创建交货单" width="650px"><el-select v-model="form.soVbeln" placeholder="选择开放销售订单" @change="loadSo"><el-option v-for="x in openSos" :key="x.vbeln" :label="`${x.vbeln} ${x.kunnr}`" :value="x.vbeln" /></el-select><el-table :data="form.items" border class="mt"><el-table-column prop="matnr" label="物料" /><el-table-column prop="openQty" label="未交数量" /><el-table-column label="本次数量"><template #default="{row}"><el-input-number v-model="row.qty" :min="0" :max="row.openQty" /></template></el-table-column></el-table><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="create">创建</el-button></template></el-dialog><el-drawer v-model="drawer" title="交货单明细" size="60%"><pre>{{JSON.stringify(selected,null,2)}}</pre></el-drawer></PageShell></template>
<script setup>
import { onMounted, reactive, ref } from 'vue'; import PageShell from '../../components/PageShell.vue'; import StatusTag from '../../components/StatusTag.vue'; import { sdApi } from '../../api'; const rows=ref([]),openSos=ref([]),visible=ref(false),drawer=ref(false),selected=ref(null),form=reactive({soVbeln:'',items:[]});async function load(){rows.value=await sdApi.dns();openSos.value=(await sdApi.sos()).filter(x=>x.status==='OPEN')};async function loadSo(){const x=await sdApi.so(form.soVbeln);form.items=(x.items||[]).map(i=>({matnr:i.matnr,openQty:i.kwmeng-(i.deliveredQty||0),qty:i.kwmeng-(i.deliveredQty||0)}))};async function create(){await sdApi.createDn(form);visible.value=false;load()};async function pick(r){await sdApi.pick(r.vbeln);load()};async function pgi(r){await sdApi.pgi(r.vbeln);load()};async function repush(r){await sdApi.repush(r.vbeln);load()};async function show(r){selected.value=await sdApi.dn(r.vbeln);drawer.value=true};onMounted(load)
</script>
